    /***
     * 遗弃
     * @param textJson
     * @return
     * @throws JsonProcessingException
     */
    public static Map<String, String> cleanseName(String textJson) throws JsonProcessingException {
        ObjectMapper objectMapper = new ObjectMapper();
        JsonNode jsonNode = objectMapper.readTree(textJson);
        Map<String, String> flattenedJson = flattenJson(jsonNode, "");
        Map<String, String> textMap = new HashMap<>();
        Map<String, String> returnMap = new HashMap<>();
        List<String> listString = new ArrayList<>();
        for (Map.Entry<String, String> entry : flattenedJson.entrySet()) {
            // 存放数据
            textMap.put(entry.getKey(),entry.getValue());
            if (
                    entry.getKey().contains(".isShared") && entry.getValue().equals("true")
            ){
                int dotIndex = entry.getKey().lastIndexOf(".");
                String result = entry.getKey().substring(0, dotIndex);
                listString.add(result);
            }
        }
        // 替换 关键字
        for (String s : listString) {
            String value = flattenedJson.get(s + ".value");
            String name = flattenedJson.get(s + ".name");

            textMap.remove(s + ".name");
            textMap.put((name+".name"),name);

            textMap.remove(s + ".value");
            textMap.put((name+".value"),value);
        }
        // 换回的map
        for (Map.Entry<String, String> t : textMap.entrySet()) {
            if (t.getKey().contains(".name")){
                returnMap.put(t.getKey(),t.getValue());
            }
            if (t.getKey().contains(".value")){
                returnMap.put(t.getKey(),t.getValue());
            }
        }
        return returnMap;
    }


    public static Map<String, String> cleanseNameByHeader(String textJson) throws JsonProcessingException {
        ObjectMapper objectMapper = new ObjectMapper();
        JsonNode jsonNode = objectMapper.readTree(textJson);
        Map<String, String> flattenedJson = flattenJson(jsonNode, "");
        Map<String, String> returnMap = new HashMap<>();
        for (Map.Entry<String, String> entry : flattenedJson.entrySet()) {
            if (entry.getKey().contains(".name")){
                returnMap.put(entry.getKey(),entry.getValue());
            }
        }
        // 转换ky
        return changeHeaderKy(returnMap);
    }

    public static Map<String, String> cleanseNameByData(String textJson) throws JsonProcessingException {
        ObjectMapper objectMapper = new ObjectMapper();
        JsonNode jsonNode = objectMapper.readTree(textJson);
        Map<String, String> flattenedJson = flattenJson(jsonNode, "");
        Map<String, String> returnMap = new HashMap<>();
        for (Map.Entry<String, String> entry : flattenedJson.entrySet()) {
            if (entry.getKey().contains(".value")){
                returnMap.put(entry.getKey(),entry.getValue());
            }
        }
        // 转换ky
        return changeDataKy(returnMap);
    }

    public static Map<String, String> flattenJson(JsonNode jsonNode, String prefix) {
        Map<String, String> flattenedJson = new HashMap<>();
        if (jsonNode.isObject()) {
            jsonNode.fields().forEachRemaining(entry -> {
                String key = prefix.isEmpty() ? entry.getKey() : prefix + "." + entry.getKey();
                flattenedJson.putAll(flattenJson(entry.getValue(), key));
            });
        } else {
            flattenedJson.put(prefix, jsonNode.asText());
        }
        return flattenedJson;
    }

    public static Map<String, String> changeHeaderKy(Map<String, String> map) {
        Map<String, String> newMap = new HashMap<>();
        for (Map.Entry<String, String> entry : map.entrySet()) {
            if (entry.getKey().contains(".name")){
                String name = entry.getKey().substring(0, entry.getKey().lastIndexOf(".name"));
                String value = entry.getValue();
                newMap.put(value,name);
            }
        }
        return newMap;
    }

    public static Map<String, String> changeDataKy(Map<String, String> map) {
        Map<String, String> newMap = new HashMap<>();
        for (Map.Entry<String, String> entry : map.entrySet()) {
            if (entry.getKey().contains(".value")){
                String name = entry.getKey().substring(0, entry.getKey().lastIndexOf(".value"));
                String value = entry.getValue();
                newMap.put(name,value);
            }
        }
        return newMap;
    }

